possible_pfs = [2, 3] + [6 * x + d for x in range(1, 5271) for d in [-1, 1]]

def LII():
	return [int(x) for x in input().split()]

def ceilq(a, b):
	return (a + b - 1) // b

def prime_factors(n):
	pfs = set({})
	for p in possible_pfs:
		if n % p == 0:
			pfs.add(p)
			while n % p == 0:
				n //= p
		if p * p > n:
			break
	if n > 1:
		pfs.add(n)
	return pfs

def copr(l, r, x):
	if x:
		y = x.copy()
		p = y.pop()
		return copr(l, r, y) - copr(ceilq(l, p), r // p, y)
	else:
		return r - l + 1
(a, b, l, r) = LII()
pfs_a = prime_factors(a)
pfs_b = prime_factors(b)
pfs_ab = pfs_a | pfs_b
print(copr(l, r, pfs_a) + copr(l, r, pfs_b) - copr(l, r, pfs_ab))
